probeSources.faiss:
#include "../../../release/extlibs/faiss/faiss_native.c"

/* 对照合法整数与小数输入，超时由父进程控制。 */
int main(int argc, char **argv)
{
    if (argc > 1 && strcmp(argv[1], "decimal") == 0) {
        printf("%.6f\n", xfaiss_l2_distance("1.5,2.5", "4.5,6.5"));
    } else {
        printf("%.6f\n", xfaiss_l2_distance("1,2", "4,6"));
    }
    return 0;
}

